"""Main source correction: visible process-leaf credit, never ancestor/flag credit."""
import fcntl
import hashlib
import json
from pathlib import Path

B = Path('/home/yayoi/.local/state/strata-sycl/post-reboot-tuning-20261007')
W = Path('/home/yayoi/ghq/github.com/yqYo1/Strata/.worktree/sync-xe-v0143-nonfinite-20261012')
sha = lambda p: hashlib.sha256(p.read_bytes()).hexdigest()

with (B / 'owned-v0141-measurement.lock').open('a') as lock:
    fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    out = B / 'xe-v0143-leaf-credit-correction-root-v1'
    assert not out.exists()
    out.mkdir(mode=0o700)
    names = ['src/core/conversation_memory.cpp', 'include/strata/core/conversation_memory.hpp',
             'tests/core/memory_guard_test.cpp']
    r = dict(passed=False, active=True, complete=False, gpu_executed=False, scope='SourceOnly correction',
             before={p: sha(W / p) for p in names}, controller_sha256=sha(Path(__file__)))
    def replace(text, old, new):
        assert text.count(old) == 1, old
        return text.replace(old, new)
    try:
        p = W / names[0]
        s = p.read_text()
        s = replace(s, '    std::ifstream stat(dir / "memory.stat");',
                    '    std::error_code ec;\n'
                    '    if (!fs::is_regular_file(fs::symlink_status(dir / "memory.stat", ec)) || ec) return 0;\n'
                    '    std::ifstream stat(dir / "memory.stat");')
        a = s.index('// What the cgroup files say:')
        b = s.index('struct CgroupScan', a)
        s = s[:a] + '// Every visible limit and its charged usage. Only an exact child-free process leaf\n' \
            '// may credit its own clean file cache; ancestor and operator-cap usage stays raw.\n' + s[b:]
        s = replace(s, '    uint64_t root_credit = 0;\n', '')
        at = s.index('// `dirs` runs')
        helper = '''// Credit applies only to a visible non-root process limit, never a partially resolved
// path, symlink or descendant subtree. Another actor may change cgroups after this
// snapshot; this is an estimate, not a reservation or proof about hidden ancestors.
bool child_free_leaf(const std::vector<fs::path>& dirs) {
    if (dirs.size() < 2) return false;
    std::error_code ec;
    for (const auto& dir : dirs) {
        if (!fs::is_directory(fs::symlink_status(dir, ec)) || ec) return false;
    }
    fs::directory_iterator it(dirs.back(), ec), end;
    if (ec) return false;
    for (; it != end; it.increment(ec)) {
        if (ec) return false;
        const auto type = it->symlink_status(ec);
        if (ec || fs::is_symlink(type) || fs::is_directory(type)) return false;
    }
    return !ec;
}

'''
        s = s[:at] + helper + s[at:]
        s = replace(s, 'const char* current_name, bool v1, CgroupScan& out)',
                    'const char* current_name, bool v1, bool exact_leaf, CgroupScan& out)')
        s = replace(s, '        const uint64_t credit = reclaimable_cache(dirs[i], current.n, v1);\n'
                    '        if (i == 0) { out.root_current = current.n; out.root_credit = credit; }',
                    '        const uint64_t credit = exact_leaf && i + 1 == dirs.size() && child_free_leaf(dirs)\n'
                    '            ? reclaimable_cache(dirs[i], current.n, v1) : 0;\n'
                    '        if (i == 0) out.root_current = current.n;')
        s = replace(s, 'std::vector<fs::path>& dirs) {\n    dirs.clear();',
                    'std::vector<fs::path>& dirs, bool& exact) {\n    dirs.clear();\n    exact = false;')
        s = replace(s, '    return true;\n}\n\nbool scan_cgroups',
                    '    exact = !group.empty() && group.front() == \'/\' && dirs.size() == names.size() + 1;\n'
                    '    return true;\n}\n\nbool scan_cgroups')
        s = replace(s, '    std::ifstream groups(paths.self_cgroup);',
                    '    unsigned v2_seen = 0, v1_seen = 0;\n    std::ifstream groups(paths.self_cgroup);')
        s = replace(s, '{ v2_group = group; continue; }', '{ v2_group = group; ++v2_seen; continue; }')
        s = replace(s, '                if (name == "memory") v1_group = group;',
                    '                if (name == "memory") { v1_group = group; ++v1_seen; }')
        s = replace(s, '    std::vector<fs::path> dirs;\n    if (v2_group)',
                    '    const bool complete_membership = groups.eof() && !groups.bad();\n'
                    '    std::vector<fs::path> dirs;\n    bool exact = false;\n    if (v2_group)')
        s = replace(s, 'group_dirs(paths.cgroup_root, *v2_group, dirs)',
                    'group_dirs(paths.cgroup_root, *v2_group, dirs, exact)')
        s = replace(s, '"memory.current", false, out)',
                    '"memory.current", false, exact && complete_membership && v2_seen == 1, out)')
        s = replace(s, 'group_dirs(fs::path(paths.cgroup_root) / "memory", *v1_group, dirs)',
                    'group_dirs(fs::path(paths.cgroup_root) / "memory", *v1_group, dirs, exact)')
        s = replace(s, '"memory.usage_in_bytes", true, out)',
                    '"memory.usage_in_bytes", true, exact && complete_membership && v1_seen == 1, out)')
        s = replace(s, 'if (cg.root_current) { used = *cg.root_current; credit = cg.root_credit; }',
                    'if (cg.root_current) used = *cg.root_current;')
        p.write_text(s)
        p = W / names[1]
        s = p.read_text()
        a = s.index('// Usage is memory.current')
        b = s.index('// Unknown telemetry', a)
        s = s[:a] + '''// Usage is memory.current as reported by the kernel. Only a fully resolved non-root
// process cgroup with no child directories may credit its clean inactive file cache
// against its own visible max/high (v1 limit), less dirty/writeback and bounded by
// current. Ancestor, namespace-root and explicit operator-cap usage stays charged
// in full: descendant protection and hidden hierarchy cannot be inferred here.
// Missing/malformed stats, symlinks or an uncertain leaf grant no credit. A leaf's
// own memory.min/low is not deducted during targeted reclaim at that leaf.
// Sampling is not a reservation; cgroup membership/children may change afterwards.
//
''' + s[b:]
        s = s.replace('what the container uses now -', 'what the container uses now:')
        p.write_text(s)
        p = W / names[2]
        s = p.read_text()
        a = s.index('    // the one credited kind')
        b = s.index('#if defined(__linux__)', a)
        block = s[a:b]
        # Preserve all parser/dirty/overflow tests on a proven non-root leaf.
        cut = block.index('        // a cgroup limit\'s own group')
        first, rest = block[:cut], block[cut:]
        first = first.replace('f.put("cgroup/memory.stat"', 'f.put("cgroup/system.slice/strata.service/memory.stat"')
        first = first.replace('f.dir / "cgroup/memory.stat"', 'f.dir / "cgroup/system.slice/strata.service/memory.stat"')
        first = first.replace('f.put("cgroup/system.slice/strata.service/memory.max", "max\\n");',
                              'f.put("cgroup/system.slice/strata.service/memory.max", 99 * GiB);')
        first = first.replace('f.put("cgroup/system.slice/strata.service/memory.current", 90 * GiB);',
                              'f.put("cgroup/system.slice/strata.service/memory.current", 98 * GiB + 324 * MiB);')
        first = first.replace('f.sample(99 * GiB)', 'f.sample()')
        first = first.replace('MemorySource::flag', 'MemorySource::cgroup')
        first = first.replace('// the operator\'s cap: the root\'s memory.current less the root\'s inactive_file; active_file and shmem are not credited',
                              '// The exact leaf credits clean inactive_file; active_file and shmem are not credited.')
        first = first.replace('the cap path credits the root\'s inactive_file', 'the exact leaf limit credits its clean inactive_file')
        rest = replace(rest, 'f.put("cgroup/system.slice/strata.service/memory.max", 92 * GiB);',
                       'f.put("cgroup/system.slice/strata.service/memory.max", 92 * GiB);\n'
                       '        f.put("cgroup/system.slice/strata.service/memory.current", 90 * GiB);')
        s = s[:a] + first + rest + s[b:]
        # A protected child subtree is never promoted to reclaimable parent credit.
        at = s.index('#if defined(__linux__)')
        extra = '''    {
        Fixture f;
        f.meminfo(120 * GiB, 25 * GiB);
        f.self("0::/a/b");
        f.put("cgroup/memory.current", 98 * GiB);
        f.put("cgroup/memory.max", "max\\n");
        f.put("cgroup/memory.stat", "inactive_file 10737418240\\n");
        f.put("cgroup/a/memory.max", 10 * GiB);
        f.put("cgroup/a/memory.current", 9 * GiB);
        f.put("cgroup/a/memory.stat", "inactive_file 8589934592\\n");
        // Incomplete membership must not promote /a to the exact process leaf.
        auto r = f.sample();
        check(r && r->available == GiB && r->credit == 0, "partial path has zero parent cache credit");
        f.put("cgroup/a/b/memory.max", 4 * GiB);
        f.put("cgroup/a/b/memory.high", 3 * GiB);
        f.put("cgroup/a/b/memory.current", 3 * GiB);
        f.put("cgroup/a/b/memory.min", 3 * GiB);
        f.put("cgroup/a/b/memory.low", 3 * GiB);
        f.put("cgroup/a/b/memory.stat", "inactive_file 536870912\\nfile_dirty 0\\nfile_writeback 0\\n");
        r = f.sample();
        check(r && r->available == 512 * MiB && r->credit == 512 * MiB,
              "a target leaf's own min/low does not remove its targeted credit");
        f.put("cgroup/a/b/child/memory.min", 3 * GiB);
        r = f.sample();
        check(r && r->available == 0 && r->credit == 0, "a child subtree gets no parent credit");
        fs::remove_all(f.dir / "cgroup/a/b/child");
        r = f.sample(98 * GiB + 128 * MiB);
        check(r && r->source == MemorySource::flag && r->available == 128 * MiB && r->credit == 0,
              "operator cap uses raw root usage even with valid leaf and root cache");
        f.self("0::/");
        r = f.sample(99 * GiB);
        check(r && r->source == MemorySource::flag && r->available == GiB && r->credit == 0,
              "namespace root is never credited");
        f.self("0::/a/b\\n0::/a/b");
        r = f.sample();
        check(r && r->available == 0 && r->credit == 0, "ambiguous membership grants no leaf credit");
#if defined(__linux__)
        f.self("0::/a/b");
        fs::create_symlink("../b", f.dir / "cgroup/a/b/link");
        r = f.sample();
        check(r && r->available == 0 && r->credit == 0, "symlink entry makes leaf credit uncertain");
        fs::remove(f.dir / "cgroup/a/b/link");
        fs::rename(f.dir / "cgroup/a/b/memory.stat", f.dir / "cgroup/a/b/real.stat");
        fs::create_symlink("real.stat", f.dir / "cgroup/a/b/memory.stat");
        r = f.sample();
        check(r && r->available == 0 && r->credit == 0, "symlink stats grant no credit");
#endif
    }
'''
        s = s[:at] + extra + s[at:]
        p.write_text(s)
        r['passed'] = True
    except BaseException as error:
        r['error'] = repr(error)
    finally:
        r.update(active=False, complete=True, after={p: sha(W / p) for p in names})
        (out / 'record.json').write_text(json.dumps(r, indent=2) + '\n')
    print(json.dumps({k: r.get(k) for k in ['passed', 'error']}))
